const mountedStages = new WeakMap();
const decodedSources = new Map();
const MAX_CACHED_SOURCES = 8;

export function getScenePreview(poemSlug, scene = 1) {
  return PREVIEWS[poemSlug]?.[scene === 0 ? 1 : scene] || '';
}

function checkScene(scene) {
  if (!Number.isInteger(scene) || scene < 0 || scene > 4) throw new RangeError('Scene must be an integer from 0 to 4.');
  return scene;
}

function decodeSource(url, reload = false) {
  if (reload) decodedSources.delete(url);
  if (decodedSources.has(url)) return decodedSources.get(url);
  const image = new Image();
  image.decoding = 'async';
  image.fetchPriority = 'high';
  const target = new URL(url);
  if (reload) target.searchParams.set('scene-retry', String(Date.now()));
  const loaded = new Promise((resolve, reject) => {
    image.onload = resolve;
    image.onerror = () => reject(new Error('Scene image could not be loaded.'));
  });
  image.src = target.href;
  const decoded = loaded.then(async () => {
    if (typeof image.decode === 'function') await image.decode();
    if (!image.naturalWidth || !image.naturalHeight) throw new Error('Scene image has no decoded pixels.');
    image.onload = null;
    image.onerror = null;
    return image;
  }).catch(error => {
    image.onload = null;
    image.onerror = null;
    if (decodedSources.get(url) === decoded) decodedSources.delete(url);
    throw error;
  });
  decodedSources.set(url, decoded);
  if (decodedSources.size > MAX_CACHED_SOURCES) decodedSources.delete(decodedSources.keys().next().value);
  return decoded;
}

function imageStyles(image) {
  Object.assign(image.style, {
    position: 'absolute', inset: '0', display: 'block', width: '100%', height: '100%',
    objectFit: 'cover', opacity: '1', animation: 'none', transition: 'none',
    transform: 'none', filter: 'none', pointerEvents: 'none'
  });
  image.alt = '';
  image.setAttribute('aria-hidden', 'true');
  image.draggable = false;
}

/**
 * Owns the container's children. Keep the container mounted during control updates.
 * Scene 0 is the readable first painting under a 15% white introductory wash.
 * show() resolves with ready/unchanged/superseded/error/destroyed; image errors keep the visible painting.
 */
export function mountStage(container, options) {
  if (!(container instanceof Element)) throw new TypeError('A scene container element is required.');
  const { poemSlug, alt = '\u53e4\u8a69\u756b\u5377', onStateChange } = options || {};
  const initialScene = checkScene(options?.scene ?? 1);
  if (!getScenePreview(poemSlug, initialScene)) throw new RangeError('Unknown poem slug.');
  mountedStages.get(container)?.destroy();
  const duration = Math.max(900, Math.min(1400, Number(options?.duration) || 1200));
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  const host = document.createElement('div');
  host.className = 'scene-stage';
  Object.assign(host.style, {
    position: 'relative', display: 'block', width: '100%', aspectRatio: '16 / 9',
    overflow: 'hidden', isolation: 'isolate', animation: 'none', transform: 'none'
  });
  const viewport = document.createElement('div');
  viewport.className = 'scene-stage-painting';
  viewport.setAttribute('role', 'img');
  viewport.setAttribute('aria-label', String(alt));
  Object.assign(viewport.style, { position: 'absolute', inset: '0', overflow: 'hidden' });
  const status = document.createElement('div');
  status.className = 'scene-stage-status';
  status.setAttribute('role', 'status');
  status.setAttribute('aria-live', 'polite');
  const statusText = document.createElement('span');
  const retryButton = document.createElement('button');
  retryButton.type = 'button';
  retryButton.textContent = '\u91cd\u65b0\u8f09\u5165';
  retryButton.setAttribute('aria-label', '\u91cd\u65b0\u8f09\u5165\u756b\u5377');
  Object.assign(retryButton.style, {
    border: '1px solid #bccfc5', borderRadius: '5px', background: '#fff', color: '#176759',
    padding: '5px 9px', minHeight: '34px', flexShrink: '0', cursor: 'pointer', font: 'inherit'
  });
  status.append(statusText, retryButton);
  host.append(viewport, status);

  let disposed = false;
  let generation = 0;
  let pending = null;
  let phase = 'loading';
  let currentScene = initialScene;
  let errorMessage = null;
  let lastRequest = { scene: initialScene, alt: String(alt), animate: true };
  let currentLayer = null;
  const layers = [];
  const animations = new Set();

  function layerFor(image, scene, quality) {
    const layer = document.createElement('div');
    layer.className = 'scene-stage-layer';
    layer.dataset.scene = String(scene);
    layer.dataset.quality = quality;
    Object.assign(layer.style, { position: 'absolute', inset: '0', opacity: '1', pointerEvents: 'none' });
    imageStyles(image);
    layer.append(image);
    if (scene === 0) {
      const wash = document.createElement('div');
      wash.className = 'scene-stage-intro-wash';
      Object.assign(wash.style, { position: 'absolute', inset: '0', background: '#fff', opacity: '.15', pointerEvents: 'none' });
      layer.append(wash);
    }
    return layer;
  }

  const preview = new Image(192, 108);
  preview.decoding = 'sync';
  preview.src = getScenePreview(poemSlug, initialScene);
  currentLayer = layerFor(preview, initialScene, 'preview');
  viewport.append(currentLayer);
  layers.push(currentLayer);
  container.replaceChildren(host);

  function getState() {
    return {
      status: disposed ? 'destroyed' : phase,
      poemSlug, scene: currentScene, requestedScene: lastRequest.scene,
      quality: currentLayer?.dataset.quality || 'preview',
      alt: viewport.getAttribute('aria-label'), error: errorMessage
    };
  }

  function publish(nextPhase, error = null) {
    phase = nextPhase;
    errorMessage = error;
    host.dataset.state = nextPhase;
    host.dataset.scene = String(currentScene);
    host.dataset.requestedScene = String(lastRequest.scene);
    viewport.setAttribute('aria-busy', String(nextPhase === 'loading'));
    const failed = nextPhase === 'error';
    status.hidden = nextPhase !== 'loading' && !failed;
    statusText.textContent = failed ? '\u756b\u5377\u66ab\u672a\u8f09\u5165\uff0c\u5df2\u4fdd\u7559\u76ee\u524d\u756b\u9762\u3002' : '\u6b63\u5728\u8f09\u5165\u756b\u5377';
    retryButton.hidden = !failed;
    if (failed) {
      status.style.cssText = 'position:absolute;left:10px;right:10px;bottom:10px;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 10px;background:rgba(255,255,255,.96);border:1px solid #dfe7e5;border-radius:6px;color:#52665c;font-size:12px;line-height:1.6;font-family:inherit;z-index:2;';
    } else {
      status.style.cssText = 'position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;';
    }
    const snapshot = getState();
    container.dispatchEvent(new CustomEvent('scenestagechange', { detail: snapshot }));
    if (typeof onStateChange === 'function') {
      try { onStateChange(snapshot); } catch (error) { console.error('Scene stage state callback failed.', error); }
    }
  }

  function removeCoveredLayers(layer) {
    const position = layers.indexOf(layer);
    if (position < 0) return;
    for (const covered of layers.splice(0, position)) {
      for (const animation of covered.getAnimations()) animation.cancel();
      covered.remove();
    }
  }

  async function fadeIn(layer, animate) {
    const motion = animate && !reducedMotion.matches && typeof layer.animate === 'function';
    if (!motion) {
      layer.style.opacity = '1';
      removeCoveredLayers(layer);
      return;
    }
    layer.style.opacity = '0';
    layer.style.willChange = 'opacity';
    const animation = layer.animate([{ opacity: 0 }, { opacity: 1 }], {
      duration, easing: 'cubic-bezier(.4, 0, .2, 1)', fill: 'forwards'
    });
    animations.add(animation);
    try { await animation.finished; } catch { return; } finally { animations.delete(animation); }
    if (disposed || !layer.isConnected) return;
    layer.style.opacity = '1';
    layer.style.willChange = 'auto';
    animation.cancel();
    removeCoveredLayers(layer);
  }

  function show(scene, nextAlt = lastRequest.alt, settings = {}) {
    checkScene(scene);
    if (disposed) return Promise.resolve({ status: 'destroyed', scene });
    const description = String(nextAlt || '\u53e4\u8a69\u756b\u5377');
    if (lastRequest.scene === scene && pending && !settings.force) {
      lastRequest.alt = description;
      if (currentScene === scene) viewport.setAttribute('aria-label', description);
      return pending;
    }
    const requestGeneration = ++generation;
    lastRequest = { scene, alt: description, animate: settings.animate !== false };
    if (currentScene === scene && currentLayer.dataset.quality === 'full' && currentLayer.style.opacity === '1' && !settings.force) {
      pending = null;
      viewport.setAttribute('aria-label', description);
      publish('ready');
      return Promise.resolve({ status: 'unchanged', scene });
    }
    publish('loading');
    const url = new URL('./media/' + poemSlug + '/scene-' + (scene || 1) + '.webp', import.meta.url).href;
    const request = (async () => {
      try {
        const source = await decodeSource(url, Boolean(settings.force));
        if (disposed) return { status: 'destroyed', scene };
        if (generation !== requestGeneration) return { status: 'superseded', scene };
        const decodedImage = source.cloneNode(false);
        if (typeof decodedImage.decode === 'function') await decodedImage.decode();
        if (disposed) return { status: 'destroyed', scene };
        if (generation !== requestGeneration) return { status: 'superseded', scene };
        const layer = layerFor(decodedImage, scene, 'full');
        layer.style.opacity = '0';
        viewport.append(layer);
        layers.push(layer);
        currentLayer = layer;
        currentScene = scene;
        viewport.setAttribute('aria-label', lastRequest.alt);
        publish(lastRequest.animate && !reducedMotion.matches ? 'transitioning' : 'ready');
        await fadeIn(layer, lastRequest.animate);
        if (disposed) return { status: 'destroyed', scene };
        if (generation !== requestGeneration) return { status: 'superseded', scene };
        publish('ready');
        return { status: 'ready', scene };
      } catch (error) {
        if (disposed) return { status: 'destroyed', scene };
        if (generation !== requestGeneration) return { status: 'superseded', scene };
        publish('error', error.message);
        return { status: 'error', scene, error: error.message };
      }
    })();
    pending = request;
    request.then(() => { if (pending === request) pending = null; }, () => { if (pending === request) pending = null; });
    return request;
  }

  function retry() {
    return show(lastRequest.scene, lastRequest.alt, { animate: lastRequest.animate, force: true });
  }

  function destroy() {
    if (disposed) return;
    disposed = true;
    generation++;
    for (const animation of animations) animation.cancel();
    animations.clear();
    reducedMotion.removeEventListener?.('change', motionChanged);
    retryButton.removeEventListener('click', retry);
    host.remove();
    if (mountedStages.get(container) === api) mountedStages.delete(container);
  }

  function motionChanged(event) {
    if (event.matches) for (const animation of animations) animation.finish();
  }

  const api = { element: host, show, retry, getState, destroy };
  retryButton.addEventListener('click', retry);
  reducedMotion.addEventListener?.('change', motionChanged);
  mountedStages.set(container, api);
  show(initialScene, alt);
  return api;
}

